import { build } from 'esbuild';
import { execFileSync } from 'node:child_process';
import { readFile, writeFile, unlink, readdir } from 'node:fs/promises';
import postcss from 'postcss';
import { createHash } from 'node:crypto';

// Embed saved summaries for direct file:// use as well as static hosting.
const snapshots = (await readdir('precomputed/benchmark')).filter(file => file.endsWith('.json')).sort();
const imports = snapshots.map((file, index) => `import snapshot${index} from "../../precomputed/benchmark/${file}";`);
await writeFile('tools-src/data/snapshots.ts', [
  '// Generated by scripts/build-tools.mjs from precomputed/benchmark/*.json.',
  'import type { OEMeasurement } from "./types";',
  ...imports,
  'export const benchmarkSnapshots: Record<string, { benchmark: string; computedAt: string; measurements: OEMeasurement[] }> = {',
  ...snapshots.map((file, index) => `  ${JSON.stringify(file.slice(0, -5))}: snapshot${index},`),
  '};', ''
].join('\n'));

const abilities = [];
for (const file of (await readdir('precomputed/model')).filter(file => file.endsWith('.json')).sort()) {
  const ability = JSON.parse(await readFile(`precomputed/model/${file}`, 'utf8'));
  const summaryHash = createHash('sha256').update(await readFile(`precomputed/benchmark/${file}`)).digest('hex');
  if (ability.summarySha256 === summaryHash) abilities.push(file);
  else console.warn(`Skipping stale ability estimate: ${file}; recompute it with scripts/compute-ability.py.`);
}
await writeFile('tools-src/data/abilities.ts', [
  '// Generated from corrected-data ability estimates by scripts/build-tools.mjs.',
  'import type { AbilitySnapshot } from "./ability-types";',
  ...abilities.map((file, i) => `import ability${i} from "../../precomputed/model/${file}";`),
  'export const abilitySnapshots: Record<string, AbilitySnapshot> = {',
  ...abilities.map((file, i) => `  ${JSON.stringify(file.slice(0, -5))}: ability${i},`),
  '};', ''
].join('\n'));

const distributions = [];
for (const file of (await readdir('precomputed/landscape')).filter(file => file.endsWith('.json')).sort()) {
  const saved = JSON.parse(await readFile(`precomputed/landscape/${file}`, 'utf8'));
  const hash = createHash('sha256').update(await readFile(`precomputed/benchmark/${file}`)).digest('hex');
  if (saved.summarySha256 === hash && saved.method === "rasch-1pl-map") distributions.push(file);
  else console.warn(`Skipping stale item distribution: ${file}`);
}
await writeFile('tools-src/data/landscape.ts', [
  '// Generated corrected item distributions.',
  ...distributions.map((file, i) => `import distribution${i} from "../../precomputed/landscape/${file}";`),
  'export const landscapeSnapshots: Record<string, {computedAt: string; metrics: Record<string, {bins: number[]; min: number; max: number; items: number; archivedItems: number; models: number; median: number | null}>}> = {',
  ...distributions.map((file, i) => `  ${JSON.stringify(file.slice(0,-5))}: distribution${i},`),
  '};', ''
].join('\n'));

await build({
  entryPoints: ['tools-src/landscape.tsx', 'tools-src/benchmark.tsx', 'tools-src/model.tsx'],
  bundle: true, outdir: '.', format: 'iife', jsx: 'automatic', target: ['es2020'],
  minify: false, legalComments: 'linked', define: { 'process.env.NODE_ENV': '"production"' },
  logOverride: { 'ignored-bare-import': 'silent' }
});
execFileSync(process.execPath, ['node_modules/@tailwindcss/cli/dist/index.mjs',
  '-i', 'tools-src/tools.css', '-o', 'tools.tmp.css', '--minify'], {stdio: 'inherit'});
const css = postcss.parse(await readFile('tools.tmp.css', 'utf8'));
css.walkAtRules('layer', rule => {
  if (rule.nodes) rule.replaceWith(...rule.nodes);
  else rule.remove();
});
// Scope utilities so class names like .container and .border cannot affect the host pages.
css.walkRules(rule => {
  if (rule.parent.type === 'atrule' && /keyframes$/.test(rule.parent.name)) return;
  rule.selectors = rule.selectors.map(selector => {
    if (selector === ':root' || selector === ':host') return '.oe-tool';
    return '.oe-tool ' + selector;
  });
});
await writeFile('tools.css', css.toString());
await unlink('tools.tmp.css');

// Embed contributor data so the contribution page also works when opened locally.
const contributors = JSON.parse(await readFile('precomputed/contributors.json', 'utf8'));
const contributionPage = await readFile('contribution.html', 'utf8');
await writeFile('contribution.html', contributionPage.replace(
  /(<script id="contributors-data" type="application\/json">)[\s\S]*?(<\/script>)/,
  (_, open, close) => open + JSON.stringify(contributors).replace(/</g, '\\u003c') + close
));
